            $this->db->prepare("UPDATE catalog_orders SET status='paid',payment_status='paid',paid_at=NOW() WHERE id=?")->execute([$orderId]);$this->db->prepare("UPDATE catalog_payment_attempts SET status='confirmed',provider_transaction_id=?,confirmed_at=NOW() WHERE id=?")->execute([$providerRef,$paymentId]);$this->event($orderId,'payment_confirmed',$order['status'],'paid',$providerRef,$actor);$payment=$this->payment($paymentId);if(!empty($payment['financial_account_id']))(new FinancialPostingCoordinator($this->db))->postIncoming('catalog_payment_attempt',$paymentId,(int)$payment['financial_account_id'],'uniforms',(string)$order['total_amount'],$actor,$providerRef);$this->db->commit();Logger::audit('catalog_payment_confirmed','catalog_order',$orderId,'Catalogue payment confirmed',['order_reference'=>$order['order_reference'],'amount'=>$order['total_amount'],'provider'=>$payment['channel']??null]);return $this->order($orderId);
        }catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }

    public function cancel(int $orderId,string $type,int $buyerId,int $actor=0): array
    {
        $this->db->beginTransaction();try{$s=$this->db->prepare('SELECT * FROM catalog_orders WHERE id=? FOR UPDATE');$s->execute([$orderId]);$o=$s->fetch(PDO::FETCH_ASSOC);if(!$o||($o['buyer_type']!==$type||(int)$o['buyer_id']!==$buyerId))throw new RuntimeException('Order not found');if(!in_array($o['status'],['pending_payment','payment_processing'],true))throw new RuntimeException('This order can no longer be cancelled');$lines=$this->db->prepare('SELECT size_id,quantity FROM catalog_order_items WHERE order_id=?');$lines->execute([$orderId]);foreach($lines as $line)$this->db->prepare('UPDATE uniform_sizes SET quantity_reserved=GREATEST(0,quantity_reserved-?) WHERE id=?')->execute([$line['quantity'],$line['size_id']]);$this->db->prepare("UPDATE catalog_orders SET status='cancelled',payment_status=IF(payment_status='paid','refunded','failed') WHERE id=?")->execute([$orderId]);$this->event($orderId,'order_cancelled',$o['status'],'cancelled',null,$actor);$this->db->commit();Logger::audit('catalog_order_cancelled','catalog_order',$orderId,'Catalogue order cancelled and reservations released',['order_reference'=>$o['order_reference'],'buyer_type'=>$type,'buyer_id'=>$buyerId]);return $this->order($orderId);}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }

    public function orders(string $type,int $buyerId): array { $this->buyer($type,$buyerId);$s=$this->db->prepare('SELECT * FROM catalog_orders WHERE buyer_type=? AND buyer_id=? ORDER BY created_at DESC');$s->execute([$type,$buyerId]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r)$r['items']=$this->orderItems((int)$r['id']);return $rows; }
    public function order(int $id): array { $s=$this->db->prepare('SELECT * FROM catalog_orders WHERE id=?');$s->execute([$id]);$o=$s->fetch(PDO::FETCH_ASSOC);if(!$o)throw new RuntimeException('Order not found');$o['items']=$this->orderItems($id);return $o; }
