    public function reviews(int $productId): array
    {
        $s=$this->db->prepare("SELECT r.id,r.rating,r.title,r.comment,r.verified_purchase,r.created_at,r.buyer_type,CASE WHEN r.buyer_type='parent' THEN COALESCE((SELECT CONCAT(pe.first_name,' ',LEFT(pe.last_name,1),'.') FROM " . ReadReplicaService::qualifiedRef('person_directory') . " pe WHERE pe.parent_id=r.buyer_id),'Parent') ELSE COALESCE((SELECT CONCAT(pe.first_name,' ',LEFT(pe.last_name,1),'.') FROM " . ReadReplicaService::qualifiedRef('person_directory') . " pe WHERE pe.user_id=r.buyer_id),'Staff member') END reviewer_name,(SELECT COUNT(*) FROM catalog_review_helpful h WHERE h.review_id=r.id) helpful_count FROM " . ReadReplicaService::qualifiedRef("catalog_reviews") . " r WHERE r.product_id=? AND r.status='published' ORDER BY r.created_at DESC");$s->execute([$productId]);return $s->fetchAll(PDO::FETCH_ASSOC);
    }
    public function saveReview(string $type,int $buyerId,array $data): array
    {
        $this->buyer($type,$buyerId);$product=(int)($data['product_id']??0);$rating=(int)($data['rating']??0);if($rating<1||$rating>5)throw new RuntimeException('Rating must be between 1 and 5');$this->product($product,$type);$v=$this->db->prepare("SELECT 1 FROM " . ReadReplicaService::qualifiedRef("catalog_orders") . " JOIN " . ReadReplicaService::qualifiedRef("catalog_order_items") . " oi ON oi.order_id=o.id WHERE o.buyer_type=? AND o.buyer_id=? AND oi.product_id=? AND o.payment_status='paid' LIMIT 1");$v->execute([$type,$buyerId,$product]);$verified=$v->fetchColumn()?1:0;$this->db->prepare("INSERT INTO catalog_reviews(product_id,buyer_type,buyer_id,rating,title,comment,status,verified_purchase) VALUES(?,?,?,?,?,?,'pending',?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),title=VALUES(title),comment=VALUES(comment),status='pending',verified_purchase=VALUES(verified_purchase),updated_at=NOW()")->execute([$product,$type,$buyerId,$rating,trim((string)($data['title']??''))?:null,trim((string)($data['comment']??''))?:null,$verified]);Logger::audit('catalog_review_submitted','catalog_product',$product,'Product review submitted for moderation',['buyer_type'=>$type,'buyer_id'=>$buyerId,'rating'=>$rating,'verified_purchase'=>(bool)$verified]);return ['submitted'=>true,'status'=>'pending','verified_purchase'=>(bool)$verified];
    }

    public function management(array $filters=[]): array
    {
        $where='1=1';$args=[];
        if(!empty($filters['status'])){$where.=' AND o.status=?';$args[]=$filters['status'];}
        $s=$this->db->prepare("SELECT o.*,CASE WHEN o.buyer_type='staff' THEN (SELECT CONCAT(p.first_name,' ',p.last_name) FROM " . ReadReplicaService::qualifiedRef('person_directory') . " p WHERE p.user_id=o.buyer_id) WHEN o.buyer_type='parent' THEN (SELECT CONCAT(p.first_name,' ',p.last_name) FROM " . ReadReplicaService::qualifiedRef('person_directory') . " p WHERE p.parent_id=o.buyer_id) ELSE 'Walk-in customer' END buyer_name,(SELECT COUNT(*) FROM " . ReadReplicaService::qualifiedRef("catalog_order_items") . " oi WHERE oi.order_id=o.id) line_count FROM " . ReadReplicaService::qualifiedRef("catalog_orders") . " o WHERE $where ORDER BY o.created_at DESC LIMIT 500");
        $s->execute($args);$orders=$s->fetchAll(PDO::FETCH_ASSOC);foreach($orders as &$order)$order['items']=$this->orderItems((int)$order['id']);unset($order);
        $summary=$this->db->query("SELECT COUNT(*) orders,COALESCE(SUM(subtotal),0) gross_value,COALESCE(SUM(discount_total),0) discounts_given,COALESCE(SUM(total_amount),0) value,COALESCE(SUM(payment_status='paid'),0) paid_orders,COALESCE(SUM(status IN ('paid','preparing','ready')),0) awaiting_fulfilment,COALESCE(SUM(source='online'),0) online_orders,COALESCE(SUM(source='internal'),0) internal_orders,COALESCE(SUM(source='physical'),0) physical_orders FROM catalog_orders")->fetch(PDO::FETCH_ASSOC);
        $legacy=$this->db->query("SELECT COUNT(*) physical_sales,COALESCE(SUM(quantity*unit_price),0) physical_value FROM uniform_sales")->fetch(PDO::FETCH_ASSOC);
        $engagement=$this->db->query("SELECT (SELECT COUNT(*) FROM " . ReadReplicaService::qualifiedRef("catalog_wishlists") . ") wishlist_count,(SELECT COUNT(*) FROM " . ReadReplicaService::qualifiedRef("catalog_reviews") . " WHERE status='pending') pending_reviews,(SELECT ROUND(AVG(rating),2) FROM " . ReadReplicaService::qualifiedRef("catalog_reviews") . " WHERE status='published') average_rating")->fetch(PDO::FETCH_ASSOC);
        $reviews=$this->db->query("SELECT r.*,p.title product_title,CASE WHEN r.buyer_type='parent' THEN 'Parent' ELSE 'Staff member' END reviewer_type FROM " . ReadReplicaService::qualifiedRef("catalog_reviews") . " JOIN " . ReadReplicaService::qualifiedRef("uniform_catalog_products") . " p ON p.id=r.product_id WHERE r.status='pending' ORDER BY r.created_at LIMIT 100")->fetchAll(PDO::FETCH_ASSOC);
        $products=$this->db->query("SELECT p.id,p.title,(SELECT COUNT(*) FROM " . ReadReplicaService::qualifiedRef("catalog_wishlists") . " w WHERE w.product_id=p.id) wishlist_count,(SELECT COUNT(*) FROM " . ReadReplicaService::qualifiedRef("catalog_reviews") . " r WHERE r.product_id=p.id AND r.status='published') review_count,(SELECT ROUND(AVG(r.rating),2) FROM " . ReadReplicaService::qualifiedRef("catalog_reviews") . " r WHERE r.product_id=p.id AND r.status='published') rating,(SELECT COALESCE(SUM(oi.quantity),0) FROM " . ReadReplicaService::qualifiedRef("catalog_order_items") . " oi JOIN " . ReadReplicaService::qualifiedRef("catalog_orders") . " o ON o.id=oi.order_id WHERE oi.product_id=p.id AND o.payment_status='paid') units_sold,(SELECT COALESCE(SUM(us.quantity_available),0) FROM " . ReadReplicaService::qualifiedRef("uniform_sizes") . " us WHERE us.item_id=p.item_id OR us.item_id IN (SELECT v.item_id FROM uniform_catalog_variants v WHERE v.product_id=p.id AND v.status='active')) available_stock,(SELECT COALESCE(SUM(us.quantity_reserved),0) FROM " . ReadReplicaService::qualifiedRef("uniform_sizes") . " us WHERE us.item_id=p.item_id OR us.item_id IN (SELECT v.item_id FROM uniform_catalog_variants v WHERE v.product_id=p.id AND v.status='active')) reserved_stock FROM " . ReadReplicaService::qualifiedRef("uniform_catalog_products") . " p ORDER BY units_sold DESC,wishlist_count DESC LIMIT 100")->fetchAll(PDO::FETCH_ASSOC);
        return ['orders'=>$orders,'summary'=>array_merge($summary,$legacy),'engagement'=>$engagement,'pending_reviews'=>$reviews,'product_analytics'=>$products];
    }

    public function scanOrderUnit(int $orderId,string $code,int $actor,?string $scanner=null): array
    {
        $this->db->beginTransaction();try{$orderStmt=$this->db->prepare('SELECT * FROM catalog_orders WHERE id=? FOR UPDATE');$orderStmt->execute([$orderId]);$order=$orderStmt->fetch(PDO::FETCH_ASSOC);if(!$order)throw new RuntimeException('Order not found');if($order['source']==='physical')throw new RuntimeException('Physical counter sales are scanned in Point of Sale');if($order['payment_status']!=='paid'||!in_array($order['status'],['paid','preparing','ready'],true))throw new RuntimeException('Only paid orders awaiting fulfilment can be packed');$stock=new CatalogStockService($this->db);$unit=$stock->lookup($code,0,null,false);$lock=$this->db->prepare('SELECT status,reserved_order_id FROM catalog_stock_units WHERE id=? FOR UPDATE');$lock->execute([$unit['id']]);$state=$lock->fetch(PDO::FETCH_ASSOC);if($state['status']==='reserved'&&(int)$state['reserved_order_id']===$orderId){$this->db->commit();return $this->orderPacking($orderId);}if($state['status']!=='in_stock')throw new RuntimeException($unit['unit_code'].' is already reserved, dispatched, or unavailable');$line=$this->db->prepare('SELECT oi.*,COUNT(su.id) scanned FROM catalog_order_items oi LEFT JOIN catalog_stock_units su ON su.order_item_id=oi.id AND su.status=\'reserved\' WHERE oi.order_id=? AND oi.product_id=? AND oi.size_id=? AND oi.variant_id <=> ? GROUP BY oi.id HAVING scanned<oi.quantity ORDER BY oi.id LIMIT 1 FOR UPDATE');$line->execute([$orderId,$unit['product_id'],$unit['size_id'],$unit['variant_id']?:null]);$item=$line->fetch(PDO::FETCH_ASSOC);if(!$item)throw new RuntimeException('This scanned product/variant/size is not required, or its quantity is already packed');$this->db->prepare("UPDATE catalog_stock_units SET status='reserved',reserved_order_id=?,order_item_id=? WHERE id=?")->execute([$orderId,$item['id'],$unit['id']]);$this->db->prepare("INSERT INTO catalog_stock_unit_events(unit_id,event_type,from_status,to_status,order_id,order_item_id,scanner_reference,notes,actor_user_id) VALUES(?,'reserved','in_stock','reserved',?,?,?,?,?)")->execute([$unit['id'],$orderId,$item['id'],$scanner,'Packed for '.$order['order_reference'],$actor]);if($order['status']==='paid'){$this->db->prepare("UPDATE catalog_orders SET status='preparing' WHERE id=?")->execute([$orderId]);$this->event($orderId,'packing_started','paid','preparing',null,$actor);}$this->db->commit();Logger::audit('catalog_order_unit_scanned','catalog_order',$orderId,'Physical unit assigned to paid order',['order_reference'=>$order['order_reference'],'unit_code'=>$unit['unit_code'],'order_item_id'=>$item['id']]);return $this->orderPacking($orderId);}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }

    public function orderPacking(int $orderId): array
    {
        $order=$this->order($orderId);$stmt=$this->db->prepare("SELECT oi.id,oi.product_title,oi.variant_name,oi.size_label,oi.quantity,COUNT(u.id) scanned FROM " . ReadReplicaService::qualifiedRef("catalog_order_items") . " LEFT JOIN " . ReadReplicaService::qualifiedRef("catalog_stock_units") . " u ON u.order_item_id=oi.id AND u.status='reserved' WHERE oi.order_id=? GROUP BY oi.id ORDER BY oi.id");$stmt->execute([$orderId]);$lines=$stmt->fetchAll(PDO::FETCH_ASSOC);$required=0;$scanned=0;foreach($lines as $line){$required+=(int)$line['quantity'];$scanned+=(int)$line['scanned'];}$order['packing_lines']=$lines;$order['required_units']=$required;$order['scanned_units']=$scanned;$order['complete']=$required>0&&$required===$scanned;return $order;
    }

    public function dispatchOrder(int $orderId,int $actor,?string $note=null): array
    {
        $this->db->beginTransaction();try{$stmt=$this->db->prepare('SELECT * FROM catalog_orders WHERE id=? FOR UPDATE');$stmt->execute([$orderId]);$order=$stmt->fetch(PDO::FETCH_ASSOC);if(!$order)throw new RuntimeException('Order not found');if($order['source']==='physical'&&$order['status']==='fulfilled'){$this->db->commit();return $this->order($orderId);}if($order['payment_status']!=='paid'||!in_array($order['status'],['paid','preparing','ready'],true))throw new RuntimeException('Only paid orders awaiting fulfilment can be dispatched');$lines=$this->db->prepare('SELECT * FROM catalog_order_items WHERE order_id=? FOR UPDATE');$lines->execute([$orderId]);$rows=$lines->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $line){$count=$this->db->prepare("SELECT COUNT(*) FROM catalog_stock_units WHERE order_item_id=? AND reserved_order_id=? AND status='reserved' FOR UPDATE");$count->execute([$line['id'],$orderId]);if((int)$count->fetchColumn()!==(int)$line['quantity'])throw new RuntimeException('Scan every unit for '.$line['product_title'].' · '.$line['size_label'].' before dispatch');}
            foreach($rows as $line){$units=$this->db->prepare("SELECT id,unit_code FROM catalog_stock_units WHERE order_item_id=? AND reserved_order_id=? AND status='reserved' FOR UPDATE");$units->execute([$line['id'],$orderId]);foreach($units->fetchAll(PDO::FETCH_ASSOC) as $unit){$this->db->prepare("UPDATE catalog_stock_units SET status='dispatched',dispatched_by=?,dispatched_at=NOW() WHERE id=?")->execute([$actor,$unit['id']]);$this->db->prepare("INSERT INTO catalog_stock_unit_events(unit_id,event_type,from_status,to_status,order_id,order_item_id,notes,actor_user_id) VALUES(?,'dispatched','reserved','dispatched',?,?,?,?)")->execute([$unit['id'],$orderId,$line['id'],$note?:'Released against '.$order['order_reference'],$actor]);}$this->db->prepare('UPDATE uniform_sizes SET quantity_available=quantity_available-?,quantity_reserved=GREATEST(0,quantity_reserved-?),quantity_sold=quantity_sold+? WHERE id=?')->execute([$line['quantity'],$line['quantity'],$line['quantity'],$line['size_id']]);$this->db->prepare('UPDATE inventory_items SET current_quantity=GREATEST(0,current_quantity-?) WHERE id=?')->execute([$line['quantity'],$line['item_id']]);if(!empty($order['student_id']))$this->db->prepare("INSERT INTO uniform_sales(student_id,item_id,size,quantity,unit_price,payment_status,sale_date,received_date,receipt_no,sold_by,notes) VALUES(?,?,?,?,?,'paid',CURDATE(),CURDATE(),?,?,?)")->execute([$order['student_id'],$line['item_id'],$line['size_label'],$line['quantity'],$line['unit_price'],$order['order_reference'].'-'.$line['id'],$actor,'Scanned catalogue dispatch '.$order['order_reference']]);}
            $this->db->prepare("UPDATE catalog_orders SET status='fulfilled',fulfilled_at=NOW() WHERE id=?")->execute([$orderId]);$this->event($orderId,'order_dispatched',$order['status'],'fulfilled',$note,$actor);$this->db->commit();Logger::audit('catalog_order_dispatched','catalog_order',$orderId,'Paid order released after complete unit scan',['order_reference'=>$order['order_reference'],'unit_count'=>array_sum(array_map(fn($line)=>(int)$line['quantity'],$rows))]);return $this->order($orderId);}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }

    public function updateOrderStatus(int $id,string $status,int $actor,?string $note=null): array
    {
        if(!in_array($status,['preparing','ready','fulfilled','cancelled'],true))throw new RuntimeException('Invalid fulfilment status');$o=$this->order($id);if($status==='cancelled')return $this->cancel($id,$o['buyer_type'],(int)$o['buyer_id'],$actor);if($status==='fulfilled')return $this->dispatchOrder($id,$actor,$note);if($o['payment_status']!=='paid')throw new RuntimeException('Only paid orders can enter fulfilment');$this->db->prepare('UPDATE catalog_orders SET status=? WHERE id=?')->execute([$status,$id]);$this->event($id,'status_changed',$o['status'],$status,$note,$actor);Logger::audit('catalog_order_status_changed','catalog_order',$id,'Catalogue fulfilment status changed',['from'=>$o['status'],'to'=>$status]);return $this->order($id);
    }

    public function moderateReview(int $id,string $status,int $actor): array { if(!in_array($status,['published','rejected'],true))throw new RuntimeException('Invalid review decision');$this->db->prepare('UPDATE catalog_reviews SET status=?,moderated_by=?,moderated_at=NOW() WHERE id=?')->execute([$status,$actor,$id]);Logger::audit('catalog_review_moderated','catalog_review',$id,'Product review moderation completed',['decision'=>$status]);return ['id'=>$id,'status'=>$status]; }
}
